import { Component, JSX, Show } from "solid-js";

import { ActivatableAudio } from "#core/ui-next/components/activatable.jsx";
import { CloseButton } from "#core/ui-next/components/close-button.jsx";
import { Panel, PanelProps } from "#core/ui-next/components/panel.jsx";
import { ComponentRegistry } from "#core/ui-next/services/component-registry.js";

export type OutsideSafezoneMode = "none" | "vertical" | "horizontal" | "full";

export interface SubsystemFrameProps extends PanelProps {
	/** Controls frame background fill outside the user safezone. */
	outsideSafezoneMode?: OutsideSafezoneMode;
	/** If true, hides the close button. */
	noClose?: boolean;
	/** Optional background image behind the panel content. */
	backdrop?: string;
	/** Optional classes applied to the header container. */
	headerClass?: string;
	/** Optional classes applied to the footer container. */
	footerClass?: string;
	/** Header content rendered above the scroll/content area. */
	header?: JSX.Element;
	/** Footer content rendered below the scroll/content area. */
	footer?: JSX.Element;
	/** Audio group ref for the close button. */
	closeButtonAudio?: ActivatableAudio;
	/** Called when the close button is activated. */
	onClose?: () => void;
}

const getFrameOutsideSafezoneClass = (mode: OutsideSafezoneMode) => {
	switch (mode) {
		case "vertical":
			return "fullscreen-outside-safezone-y";
		case "horizontal":
			return "fullscreen-outside-safezone-x";
		case "full":
			return "fullscreen-outside-safezone";
		default:
			mode satisfies "none";
			return "";
	}
};

const SubsystemFrameB1 = (props: SubsystemFrameProps) => {
	return (
		<Panel
			{...props}
			class={`relative flex flex-col pt-4 px-6 ${props.class ?? ""}`}
		>
			<div
				class={`inset-0 absolute frame-top-curve ${getFrameOutsideSafezoneClass(props.outsideSafezoneMode ?? "none")}`}
			/>

			<div class="relative flex flex-col items-center self-stretch">
				<div class="flex flex-row min-w-96 -mt-8">
					<div class="filigree-panel-top-left" />
					<div class="filigree-panel-top-right" />
				</div>
			</div>

			<Show when={!!props.backdrop}>
				<div class="absolute size-full pointer-events-none">
					<div
						class="relative bg-no-repeat bg-cover -mb-4 grow mx-3\\.5"
						style={{ "background-image": `url(${props.backdrop})` }}
					/>
				</div>
			</Show>

			<div class="flex-auto max-w-full relative">
				{props.header}

				<div class="flex-auto mx-3\\.5">{props.children}</div>

				{props.footer}
			</div>

			<Show when={!props.noClose}>
				<CloseButton
					class="absolute top-1 right-1"
					audio={{
						onPress: "data-audio-close-press",
						onActivate: "data-audio-close-selected",
						...props.closeButtonAudio,
					}}
					onActivate={() => props.onClose?.()}
					aria-label="Close"
				/>
			</Show>
		</Panel>
	);
};

