export type SubsystemFrameComponents = Component<SubsystemFrameProps> & {
	/**
	 * Subsystem Frame B1 style.
	 * See {@link SubsystemFrameProps} for prop details.
	 *
	 * Example:
	 * ```tsx
	 * <SubsystemFrame.B1
	 *   name="tech-tree"
	 *   header={<Header>...</Header>}
	 *   footer={<Button>...</Button>}
	 *   onClose={...}
	 * >
	 *   ...content...
	 * </SubsystemFrame.B1>
	 * ```
	 */
	B1: Component<SubsystemFrameProps>;
	/**
	 * Subsystem Frame B2 style.
	 * See {@link SubsystemFrameProps} for prop details.
	 *
	 * Example:
	 * ```tsx
	 * <SubsystemFrame.B2
	 *   name="diplomacy"
	 *   header={<Header>...</Header>}
	 *   footer={<Button>...</Button>}
	 * >
	 *   ...content...
	 * </SubsystemFrame.B2>
	 * ```
	 */
	B2: Component<SubsystemFrameProps>;
	/**
	 * Subsystem Frame B3 style.
	 * See {@link SubsystemFrameProps} for prop details.
	 *
	 * Example:
	 * ```tsx
	 * <SubsystemFrame.B3
	 *   name="diplomacy-detailed"
	 *   header={<Header>...</Header>}
	 * >
	 *   ...content...
	 * </SubsystemFrame.B3>
	 * ```
	 */
	B3: Component<SubsystemFrameProps>;
	/**
	 * Subsystem Frame B4 style.
	 * See {@link SubsystemFrameProps} for prop details.
	 *
	 * Example:
	 * ```tsx
	 * <SubsystemFrame.B4
	 *   name="civic-chooser"
	 *   header={<Header>...</Header>}
	 * >
	 *   ...content...
	 * </SubsystemFrame.B4>
	 * ```
	 */
	B4: Component<SubsystemFrameProps>;
	/**
	 * Subsystem Frame Fullscreen style.
	 * See {@link SubsystemFrameProps} for prop details.
	 *
	 * Example:
	 * ```tsx
	 * <SubsystemFrame.Fullscreen
	 *   name="civilopedia"
	 *   header={<Header>...</Header>}
	 *   onClose={...}
	 * >
	 *   ...content...
	 * </SubsystemFrame.Fullscreen>
	 * ```
	 */
	Fullscreen: Component<SubsystemFrameProps>;
};

export const SubsystemFrame = ComponentRegistry.register({
	name: "SubsystemFrame",
	createInstance: SubsystemFrameB1,
	images: ["blp:hud_squarepanel-bg.png"],
}) as SubsystemFrameComponents;

